from pathlib import Path
import pandas as pd, numpy as np
import plotly.graph_objects as go
from plotly.subplots import make_subplots
import plotly.express as px

# Load
csv_path=Path('benchmark/data.csv')
df=pd.read_csv(csv_path, parse_dates=['order_date'])

# Derived fields
with np.errstate(divide='ignore', invalid='ignore'):
    df['profit_margin']=np.where(df['revenue']!=0, df['profit']/df['revenue'], np.nan)

df['year']=df['order_date'].dt.year

df['month']=df['order_date'].dt.to_period('M').dt.to_timestamp()

# KPIs
total_revenue=float(df['revenue'].sum())
total_profit=float(df['profit'].sum())
avg_profit_margin=float(df['profit_margin'].mean())
avg_order_value=float(df['revenue'].mean())
discount_util=float((df['discount']>0).mean())
orders=int(df['order_id'].nunique())

# Time series monthly
monthly=df.groupby('month').agg(revenue=('revenue','sum'), profit=('profit','sum'), orders=('order_id','nunique'))
monthly=monthly.reset_index().sort_values('month')
monthly['year']=monthly['month'].dt.year
monthly['month_of_year']=monthly['month'].dt.month

# Monthly YOY percent for same month
pivot_rev=monthly.pivot(index='month_of_year', columns='year', values='revenue')
pivot_orders=monthly.pivot(index='month_of_year', columns='year', values='orders')
yoy_rev=((pivot_rev[2024]-pivot_rev[2023])/pivot_rev[2023])
yoy_orders=((pivot_orders[2024]-pivot_orders[2023])/pivot_orders[2023])

# Quarterly
q=df.copy()
q['quarter']=q['order_date'].dt.to_period('Q').astype(str)
quarterly=q.groupby('quarter').agg(revenue=('revenue','sum'), profit=('profit','sum'), orders=('order_id','nunique')).reset_index()

# Product and store performance (fact only)
prod=df.groupby('product_id').agg(revenue=('revenue','sum'), profit=('profit','sum'), orders=('order_id','nunique')).reset_index()
prod['profit_margin']=prod['profit']/prod['revenue']
prod_top_rev=prod.sort_values('revenue', ascending=False).head(10)
prod_top_profit=prod.sort_values('profit', ascending=False).head(10)

store=df.groupby('store_id').agg(revenue=('revenue','sum'), profit=('profit','sum'), orders=('order_id','nunique')).reset_index()
store['profit_margin']=store['profit']/store['revenue']
store_top_rev=store.sort_values('revenue', ascending=False).head(10)
store_bottom_rev=store.sort_values('revenue', ascending=True).head(10)

# Discount impact
# The dataset contains 0, 0.1, 0.15, 0.2 (and maybe others). We'll bucket by exact rounded percentage.
disc=df.copy()
disc['discount_pct']=(disc['discount']*100).round(2)
# Create categorical ordering
levels=sorted(disc['discount_pct'].unique())
# Keep common levels ordered
levels_order=[lvl for lvl in [0.0,5.0,10.0,15.0,20.0] if lvl in levels] + [lvl for lvl in levels if lvl not in [0.0,5.0,10.0,15.0,20.0]]
disc['discount_level']=pd.Categorical(disc['discount_pct'], categories=levels_order, ordered=True)
disc_agg=disc.groupby('discount_level', observed=True).agg(
    orders=('order_id','nunique'),
    quantity=('quantity','sum'),
    revenue=('revenue','sum'),
    profit=('profit','sum'),
    avg_margin=('profit_margin','mean'),
    avg_order_value=('revenue','mean'),
).reset_index()
disc_agg['profit_margin_total']=disc_agg['profit']/disc_agg['revenue']

# Customer insights (limited: no demographics/loyalty columns in provided CSV)
cust=df.groupby('customer_id').agg(orders=('order_id','nunique'), revenue=('revenue','sum'), profit=('profit','sum'), quantity=('quantity','sum'))
cust['aov']=cust['revenue']/cust['orders']
# concentration
cust_sorted=cust.sort_values('revenue', ascending=False)
rev_total=float(cust_sorted['revenue'].sum())
share_1=float(cust_sorted.head(max(1,int(len(cust_sorted)*0.01)))['revenue'].sum()/rev_total)
share_5=float(cust_sorted.head(max(1,int(len(cust_sorted)*0.05)))['revenue'].sum()/rev_total)
share_10=float(cust_sorted.head(max(1,int(len(cust_sorted)*0.10)))['revenue'].sum()/rev_total)

